<?php require __DIR__.'/_auth.php'; ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Serviços · Larissa Beauty</title><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Montserrat:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/admin.css"></head><body><div class="app"><nav class="menu"><a class="marca" href="dashboard.php">Larissa Beauty</a><a class="link" href="dashboard.php">Início</a><a class="link" href="agenda.php">Agenda</a><a class="link on" href="servicos.php">Serviços</a><a class="link" href="horarios.php">Horários</a><a class="link sair" href="#" id="sair">Sair</a></nav><main class="conteudo"><div class="cabeca"><div><h1>Serviços</h1><p>O que aparece para a cliente escolher no agendamento.</p></div></div><form class="form-linha" id="novo"><label>Nome<input name="nome" required></label><label>Preço (R$)<input name="preco" type="number" min="0" step="0.01" required></label><label>Duração (minutos)<input name="duracao_minutos" type="number" min="1" step="1" required></label><button class="btn">Adicionar</button></form><div id="msg" class="resumo"></div><div class="lista" id="lista"><div class="vazio">Carregando serviços do banco...</div></div></main></div><script>
async function api(m,d){const o={method:m,credentials:'same-origin',cache:'no-store',headers:{}};if(d){const me=await fetch('../backend/api/me.php',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json());if(!me.csrf)throw Error('Sessão expirada. Entre novamente.');o.headers['Content-Type']='application/json';o.headers['X-CSRF-Token']=me.csrf;o.body=JSON.stringify(d);}const r=await fetch('../backend/api/admin_servicos.php',o);const x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.erro||'Falha ('+r.status+')');return x;}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const reais=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});let rows=[];const lista=document.getElementById('lista'),msg=document.getElementById('msg');
async function load(){try{rows=(await api('GET')).servicos;lista.innerHTML=rows.map(s=>`<div class="item simples ${Number(s.ativo)?'':'inativo'}"><div><span class="nome">${esc(s.nome)}</span><small>${reais(s.preco)} · ${s.duracao_minutos} min</small></div><div class="acoes"><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" class="chave" data-id="${s.id}" ${Number(s.ativo)?'checked':''}> ${Number(s.ativo)?'Ativo':'Inativo'}</label><button class="btn perigo" data-rm="${s.id}">Desativar</button></div></div>`).join('')||'<div class="vazio">Nenhum serviço cadastrado.</div>';}catch(e){lista.innerHTML='<div class="vazio">'+esc(e.message)+'</div>';}}
lista.addEventListener('change',async e=>{if(!e.target.matches('[data-id]'))return;try{await api('PATCH',{id:Number(e.target.dataset.id),ativo:e.target.checked?1:0});await load();}catch(x){alert(x.message);}});lista.addEventListener('click',async e=>{const b=e.target.closest('[data-rm]');if(!b)return;if(!confirm('Desativar este serviço? O histórico de agendamentos será preservado.'))return;try{await api('DELETE',{id:Number(b.dataset.rm)});await load();}catch(x){alert(x.message);}});document.getElementById('novo').addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.preco=Number(d.preco);d.duracao_minutos=Number(d.duracao_minutos);try{await api('POST',d);e.target.reset();msg.textContent='Serviço cadastrado no banco.';await load();}catch(x){msg.textContent=x.message;}});document.getElementById('sair').onclick=async e=>{e.preventDefault();const me=await fetch('../backend/api/me.php').then(r=>r.json());await fetch('../backend/api/logout.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':me.csrf},body:'{}'});location.href='login.php';};load();</script></body></html>